Definition rd_cell_B (mem : word -> option byte) (a : Z) (n : nat) (v : Z) : Prop :=
  exists bs, rdn SEGS_B mem (Z_to_bv 64 a) n = Some bs /\ bytes_le_to_Z bs = v.
Definition rd_u64_B (mem : word -> option byte) (a v : Z) : Prop := rd_cell_B mem a 8 v.
Definition rd_cells_ok_B (l : list (Z * Z)) (mem : word -> option byte) : Prop := forall a b, In (a, b) l -> rd_cell_B mem a 1 b.

Definition rt_ok_B (mem : word -> option byte) : Prop := rd_cells_ok_B RT_B mem.     (* [comment removed for export] *)
Definition gsh_ok_B (mem : word -> option byte) : Prop := cells_ok GSH_B mem.


