Record fs_inv_B (FS : Z) (mem : word -> option byte) : Prop := FsInvB {
  fiB_tls   : rd_u64_B mem FSTLS_B FS;                  (* [comment removed for export] *)
  fiB_align : FS mod 4096 = 0;
  fiB_lo    : IMGHI_A <= FS;                        (* [comment removed for export] *)
  fiB_app   : app_mem FS FS_LEN;                     (* [comment removed for export] *)
  fiB_hi    : FS + FS_LEN <= HIEND_A;
  fiB_def   : mem_def mem FS FS_LEN;
  fiB_shdef : mem_def mem (sh FS + FS_SHLO) (FS_SHHI - FS_SHLO);
  fiB_log   : mem_u64 mem (FS + 88) 20;
  fiB_gc    : mem_byte mem (FS + 96) 0;
  fiB_flags : forall j, 0 <= j < 32768 -> mem_byte mem (FS + FS_FLAGS + j) 0
}.

