(* [comment removed for export] *)
Definition malloc_ctx_ok_B (wlo whi FS : Z) (mem : word -> option byte) : Prop :=
  exists CTX THR DT,
       rd_u64_B mem 0x687ca0 CTX /\ mem_u64 mem (CTX + 0x98) THR /\ mem_def mem (THR + 0x30) 16
    /\ rd_u64_B mem 0x6667f0 DT /\ mem_u64 mem (DT + 0x18) TP_B
    /\ 0 <= CTX /\ CTX + 0xa0 <= HIEND_A /\ 0 <= THR /\ 0 <= DT
    /\ ctx_cell_ok wlo whi FS (CTX + 0x98) 8 /\ ctx_cell_ok wlo whi FS (THR + 0x30) 16 /\ ctx_cell_ok wlo whi FS (DT + 0x18) 8.


(* [comment removed for export] *)
Definition MALLOC_B (k : Z) : Z := if k =? 1 then 0x5b488 else if k =? 4 then 0x5b618 else 0x5b7e4.
Definition FREE5_B : Z := 0x5b9f0.
Definition CBD_ENTRY_B : Z := 0xa9444. 
Definition CBD_FR_B : Z := 3072.
Definition CBD_TBL_LO_B : Z := 0x237e0.            (* [comment removed for export] *)
Definition CBD_TBL_HI_B : Z := 0x23810.

(* [comment removed for export] *)
Definition lib_stmt_B : Prop :=
  forall (fx : FPState) (regs : bvmap 5 word) (mem rom : word -> option byte) (ret sp data : word) (n FS : Z),
    getr regs (Z_to_bv 5 1) = ret -> bv_unsigned ret mod 4 = 0 ->
    getr regs (Z_to_bv 5 2) = sp -> getr regs (Z_to_bv 5 10) = data -> getr regs (Z_to_bv 5 11) = Z_to_bv 64 n ->
    getr regs (Z_to_bv 5 4) = w64 TP_B ->
    0 <= n < NMAX_A ->
    4096 <= bv_unsigned data -> bv_unsigned data + n + 4096 < 2 ^ 62 -> bv_unsigned data mod 16 = 0 ->
    bv_unsigned sp mod 16 = 0 -> 2 ^ 32 <= bv_unsigned sp - FR_A -> bv_unsigned sp < 2 ^ 62 ->
    (bv_unsigned data + n <= bv_unsigned sp - FR_A \/ bv_unsigned sp <= bv_unsigned data) ->
    (n = 0 \/ bv_unsigned data + n <= 0x10000 \/ 0x688000 <= bv_unsigned data) ->   (* [comment removed for export] *)
    (forall a, bv_unsigned sp - FR_A <= a < bv_unsigned sp -> find_segment SEGS_B a 1 = None) ->
    (forall i, 0 <= i < n -> exists b, rdn SEGS_B mem (Z_to_bv 64 (bv_unsigned data + i)) 1 = Some [b]) ->
    store_ok SEGS_B mem (Z_to_bv 64 (bv_unsigned sp - FR_A)) (Z.to_nat FR_A) = true ->
    ro_ok SEGS_B RO_B mem ->
    (exists c : word, rdn SEGS_B mem (Z_to_bv 64 CANARY_B) 8%nat = Some (word_to_le_bytes 8 c)) ->   (* [comment removed for export] *)
    lib_statics LIBR_HULL_B LIBR_B SNAP_B mem ->
    (* [comment removed for export] *)
    rt_ok_B mem -> gsh_ok_B mem ->
    stack_shadow_ok (bv_unsigned sp) mem -> payload_shadow_ok (bv_unsigned data) n mem ->
    fs_inv_B FS mem -> malloc_ctx_ok_B (bv_unsigned sp - FR_A) (bv_unsigned sp) FS mem ->
    apart_A (bv_unsigned sp) (bv_unsigned data) n FS ->
    frm_zero fx ->
    exists (fx' : FPState) (regs' : bvmap 5 word) (mem' : word -> option byte),
         @msteps SEGS_B (@mkst fx regs (w64 ENTRY_B) mem rom) (@mkst fx' regs' ret mem' rom)
      /\ keeps_cs regs regs'
      /\ getr regs' (Z_to_bv 5 10) = Z_to_bv 64 0
      /\ mem_frame mem mem' ((bv_unsigned sp - FR_A, bv_unsigned sp) :: LIBR_B
                             ++ [(FS, FS + FS_LEN); (sh FS + FS_SHLO, sh FS + FS_SHHI)])
      /\ lib_statics LIBR_HULL_B LIBR_B SNAP_B mem'
      /\ fs_inv_B FS mem'
      /\ frm_zero fx'.


(* [comment removed for export] *)
Definition malloc_stmt_B (k : Z) : Prop :=
  forall (fx : FPState) (regs : bvmap 5 word) (mem rom : word -> option byte) (ret : word) (sp FS : Z) (fl : Z -> Z),
    getr regs (Z_to_bv 5 1) = ret -> bv_unsigned ret mod 4 = 0 ->
    getr regs (Z_to_bv 5 2) = w64 sp -> sp mod 16 = 0 -> KHI_A <= sp - MALLOC_FR -> sp <= HIEND_A ->
    mem_def mem (sp - MALLOC_FR) MALLOC_FR ->
    getr regs (Z_to_bv 5 4) = w64 TP_B ->
    rt_ok_B mem -> ro_ok SEGS_B RO_B mem -> malloc_ctx_ok_B (sp - MALLOC_FR) sp FS mem ->
    rd_u64_B mem FSTLS_B FS -> FS mod 4096 = 0 -> IMGHI_A <= FS -> app_mem FS FS_LEN -> FS + FS_LEN <= HIEND_A ->   (* [comment removed for export] *)
    (sp <= FS \/ FS + FS_LEN <= sp - MALLOC_FR) ->
    mem_def mem FS FS_LEN -> mem_def mem (sh FS + FS_SHLO) (FS_SHHI - FS_SHLO) ->
    mem_u64 mem (FS + 88) 20 -> mem_byte mem (FS + 96) 0 ->
    (forall j, 0 <= j < fs_N k -> mem_byte mem (fs_flag FS k j) (fl j) /\ (fl j = 0 \/ fl j = 1)) ->
    (exists j, 0 <= j < fs_N k /\ fl j = 0) ->
    exists (regs' : bvmap 5 word) (mem' : word -> option byte) (p : Z),
         @msteps SEGS_B (@mkst fx regs (w64 (MALLOC_B k)) mem rom) (@mkst fx regs' ret mem' rom)
      /\ keeps_cs regs regs'
      /\ 0 <= p < fs_N k /\ fl p = 0
      /\ getr regs' (Z_to_bv 5 10) = w64 (fs_frame FS k p)
      /\ mem_byte mem' (fs_flag FS k p) 1
      /\ mem_u64 mem' (fs_frame FS k p + fs_fsz k - 8) (fs_flag FS k p)
      /\ (forall t, 0 <= t < fs_fsz k / 8 -> mem_byte mem' (sh (fs_frame FS k p) + t) 0)
      /\ mem_frame mem mem' [(sp - MALLOC_FR, sp); (fs_hint FS k, fs_hint FS k + 8); (fs_flag FS k p, fs_flag FS k p + 1);
                            (fs_frame FS k p + 24, fs_frame FS k p + 32); (fs_frame FS k p + fs_fsz k - 8, fs_frame FS k p + fs_fsz k);
                            (sh (fs_frame FS k p), sh (fs_frame FS k p) + fs_fsz k / 8)].


Definition free5_stmt_B : Prop :=
  forall (fx : FPState) (regs : bvmap 5 word) (mem rom : word -> option byte) (ret : word) (sp f q : Z),
    getr regs (Z_to_bv 5 1) = ret -> bv_unsigned ret mod 4 = 0 ->
    getr regs (Z_to_bv 5 2) = w64 sp -> sp mod 16 = 0 -> KHI_A <= sp - FREE5_FR -> sp <= HIEND_A ->
    mem_def mem (sp - FREE5_FR) FREE5_FR ->
    getr regs (Z_to_bv 5 10) = w64 f -> f mod 8 = 0 -> IMGHI_A <= f -> app_mem f 2048 -> f + 2048 <= HIEND_A ->   (* [comment removed for export] *)
    mem_u64 mem (f + 2040) q -> IMGHI_A <= q -> app_mem q 1 -> q < HIEND_A -> mem_def mem q 1 ->               (* [comment removed for export] *)
    mem_def mem (sh f) 256 ->
    (* [comment removed for export] *)
    (q + 1 <= sp - FREE5_FR \/ sp <= q) -> (sh f + 256 <= sp - FREE5_FR \/ sp <= sh f) ->
    (f + 2048 <= sp - FREE5_FR \/ sp <= f) -> (q + 1 <= sh f \/ sh f + 256 <= q) -> (q + 1 <= f \/ f + 2048 <= q) ->
    rt_ok_B mem -> ro_ok SEGS_B RO_B mem ->
    exists (regs' : bvmap 5 word) (mem' : word -> option byte),
         @msteps SEGS_B (@mkst fx regs (w64 FREE5_B) mem rom) (@mkst fx regs' ret mem' rom)
      /\ keeps_cs regs regs'
      /\ mem_byte mem' q 0
      /\ (forall t, 0 <= t < 256 -> mem_byte mem' (sh f + t) 0xf5)
      /\ mem_frame mem mem' [(sp - FREE5_FR, sp); (q, q + 1); (sh f, sh f + 256)].


(* [comment removed for export] *)
Definition cbd_writes_B (sp FS : Z) : list (Z * Z) :=
  [(sp - CBD_FR_B, sp); (fs_hint FS 5, fs_hint FS 5 + 8); FS5_FLAGS FS; FS5_FRAMES FS; FS5_SHADOW FS].

Definition cbd_stmt_B : Prop :=
  forall (fx : FPState) (regs : bvmap 5 word) (mem rom : word -> option byte)
         (sp buf len expo e a4 FS : Z) (ret f : word),
    getr regs (Z_to_bv 5 1) = ret -> bv_unsigned ret mod 4 = 0 ->
    getr regs (Z_to_bv 5 2) = Z_to_bv 64 sp -> sp mod 16 = 0 -> KHI_A <= sp - CBD_FR_B -> sp <= HIEND_A ->
    getr regs (Z_to_bv 5 4) = w64 TP_B ->
    getr regs (Z_to_bv 5 10) = Z_to_bv 64 buf -> IMGHI_A <= buf -> app_mem buf len -> buf + len <= HIEND_A ->   (* [comment removed for export] *)
    getr regs (Z_to_bv 5 11) = Z_to_bv 64 len -> getr regs (Z_to_bv 5 12) = Z_to_bv 64 expo ->
    getr regs (Z_to_bv 5 13) = f -> getr regs (Z_to_bv 5 14) = Z_to_bv 64 a4 -> a4 mod 2 ^ 32 = e mod 2 ^ 32 ->
    1 <= len <= 780 -> -323 <= len + expo <= 309 -> -2047 <= e <= 2047 ->
    (forall i, 0 <= i < len ->
       exists d, rdn SEGS_B mem (Z_to_bv 64 (buf + i)) 1 = Some [d] /\ 48 <= bv_unsigned d <= 57) ->
    (forall i, 0 <= i < len -> mem_byte mem (sh (buf + i)) 0) ->            (* [comment removed for export] *)
    mem_def mem (sp - CBD_FR_B) CBD_FR_B ->
    (sp <= buf \/ buf + len <= sp - CBD_FR_B) ->
    ro_ok SEGS_B RO_B mem -> rt_ok_B mem -> gsh_ok_B mem -> malloc_ctx_ok_B (sp - CBD_FR_B) sp FS mem ->
    rd_u64_B mem FSTLS_B FS -> FS mod 4096 = 0 -> IMGHI_A <= FS -> app_mem FS FS_LEN -> FS + FS_LEN <= HIEND_A ->   (* [comment removed for export] *)
    (sp <= FS \/ FS + FS_LEN <= sp - CBD_FR_B) ->
    (forall r, In r (cbd_writes_B sp FS) -> buf + len <= fst r \/ snd r <= buf) ->
    (forall r, In r (cbd_writes_B sp FS) -> sh (buf + len - 1) + 1 <= fst r \/ snd r <= sh buf) ->
    mem_def mem FS FS_LEN -> mem_def mem (sh FS + FS_SHLO) (FS_SHHI - FS_SHLO) ->
    mem_u64 mem (FS + 88) 20 -> mem_byte mem (FS + 96) 0 ->
    (forall j, 0 <= j < 512 -> mem_byte mem (fs_flag FS 5 j) 0) ->
    (forall g, (sp - CBD_FR_B) / 8 <= g < sp / 8 -> mem_byte mem (SH_A + g) 0) ->
    exists (regs' : bvmap 5 word) (mem' : word -> option byte),
         @msteps SEGS_B (@mkst fx regs (Z_to_bv 64 CBD_ENTRY_B) mem rom) (@mkst fx regs' ret mem' rom)
      /\ keeps_cs regs regs'
      /\ (exists r, getr regs' (Z_to_bv 5 10) = Z_to_bv 64 r /\ -1 <= r <= 1)
      /\ (forall j, 0 <= j < 512 -> mem_byte mem' (fs_flag FS 5 j) 0)
      /\ mem_frame mem mem' (cbd_writes_B sp FS).

